"""Normalize already completed manual phase1 reviews; never executes candidates."""
from pathlib import Path
import hashlib,json,time
A=Path(__file__).resolve().parent
reviews={p.name.removesuffix('.audit.json'):json.loads(p.read_text()) for p in A.glob('*.audit.json')}
assert len(reviews)==40, f"Need40 immutable reviews, found{len(reviews)}"
X={s:json.loads((A/(s+'.extraction.json')).read_text()) for s in reviews}
records=list(reviews.values())
