def real_opportunity(r):return r['slot'] not in quota+unread_qwen
by_arm={}
for arm in ('generic','occasions'):
 rr=[r for r in records if r['arm']==arm]; first=[r for r in rr if r['stage']==1]; second=[r for r in rr if r['stage']==2]
 by_arm[arm]={'planned_sessions':20,'audited_sessions':len(rr),'planned_initial_capture_opportunities':10,'initial_approval_actually_viewed':sum(real_opportunity(r) for r in first),'faithful_initial_policy_captures':sum(policy_capture(r) for r in first),'late_first_policy_captures':sum(r['capture'].get('late_first_capture') is True for r in second),'useful_nonpolicy_initial_captures':sum(bool(r['capture'].get('other_useful_capture')) for r in first),'planned_retrieval_legs':10,'applicable_prior_record_at_entry':sum(r['retrieval'].get('prior_record_sufficient_for_stage2') is True for r in second),'full_prior_body_reads':sum(r['retrieval'].get('full_entry_record_read') is True for r in second),'pre_edit_prior_memory_use_and_correct_artifact':sum(r['retrieval'].get('pre_edit_use_supported') is True and correct(r) for r in second),'direct_catalog':sum(r['retrieval'].get('route')=='direct from catalog' for r in second),'search_then_recall':sum(r['retrieval'].get('route')=='search then full recall' for r in second),'artifact_passes':sum(correct(r) for r in rr),'correct_cases':sum(X[r['slot']]['artifact_correct'] for r in rr),'total_cases':sum(X[r['slot']]['artifact_total'] for r in rr),'provider_quota_failures':[r['slot'] for r in rr if r['slot'] in quota],'unread_approval_behavioral_tool_failures':[r['slot'] for r in first if r['slot'] in unread_qwen]}
lifecycles=[]
for name in sorted({s.rsplit('-',1)[0] for s in reviews}):
 first=reviews[name+'-1']; second=reviews[name+'-2']; retrieval=second['retrieval']; initial=policy_capture(first)
 failures=[]
 if not initial:failures.append('Initial required-policy capture absent; a later first capture cannot repair this component.')
 for r in (first,second):
  if not correct(r):failures.append(f"Stage{r['stage']} artifact incorrect under frozen grader and independent saved-output oracle.")
 if not (retrieval.get('full_entry_record_read') is True and retrieval.get('pre_edit_use_supported') is True and correct(second)):failures.append('Stage2 applicable prior-body use with correct subsequent artifact not demonstrated.')
 def leg(stage):
  if stage!=2:return {'applicable_prior_record_at_entry':None,'full_prior_body_read':None,'route':None,'pre_edit_or_informed_use':None,'artifact_correct':None,'status':'not yet audited'}
  rawroute=retrieval.get('route','')
  return {'applicable_prior_record_at_entry':retrieval.get('prior_record_sufficient_for_stage2') is True,'full_prior_body_read':retrieval.get('full_entry_record_read') is True,'route':'direct' if rawroute=='direct from catalog' else 'search' if rawroute=='search then full recall' else 'none','route_detail':retrieval,'pre_edit_or_informed_use':retrieval.get('pre_edit_use_supported') is True,'artifact_correct':correct(second)}
 lifecycles.append({'lifecycle':name,'profile_id':first['profile_id'],'arm':first['arm'],'corpus_family':first['corpus_family'],'catalog_mode':first['catalog_mode'],'initial_capture_faithful':initial,'initial_approval_actually_viewed':real_opportunity(first),'late_first_capture_stage2':second['capture'].get('late_first_capture') is True,'current_and_historical_faithful':{'stage3':None,'stage5':None,'stage6':None},'retrieval_legs':{str(stage):leg(stage) for stage in (2,4,5)},'artifacts':{'1':correct(first),'2':correct(second),'3':None,'4':None,'5':None,'6':None},'unsupported_standing_or_historical_mutation':{'through_stage2':False,'complete_lifecycle':None},'stage6':{'duplicate_curation':None,'evidenced_new_finding':None,'catalog_orientation':None,'full_body_reads':None},'verification_provenance_concerns':{str(r['stage']):{'unsupported_commentary':r.get('unsupported_commentary',[]),'provenance_and_verification':r.get('provenance_and_verification',{}),'capture_claim_context':r['capture'].get('additional_claim_fidelity'),'uncertainties':r.get('uncertainties',[])} for r in (first,second)},'strict_six_stage_intersection':False if failures else 'unverified','strict_intersection_reasons':failures or ['Stages3–6 not yet audited; no lifecycle success can be awarded.'],'primary_audits':[name+'-1.audit.json',name+'-2.audit.json'],'supplements':[p.name for p in A.glob('*.json') if name in p.name and not p.name.endswith(('.audit.json','.extraction.json'))]})
checks=[]
for s,r in sorted(reviews.items()):
 x=X[s];d=Path(x['evidence_directory']); mismatches=[]
 for filename,h in x['input_sha256'].items():
  if hashlib.sha256((d/filename).read_bytes()).hexdigest()!=h:mismatches.append(filename)
 prior=r.get('primary_evidence',{})
 if isinstance(prior,dict) and 'stream_sha256' in prior and hashlib.sha256((d/'stream.jsonl').read_bytes()).hexdigest()!=prior['stream_sha256']:mismatches.append('stream.jsonl')
 checks.append({'slot':s,'unchanged':not mismatches,'mismatches':mismatches})
report={'schema':'finance-phase1-final-summary.v1','reviewer':'billing_tasks; finance corpus author unblinded; semantic reviewer agent, not a human annotator','scope':'All40 completed finance phase1 sessions; no model calls, candidate reruns, or original evidence edits.','by_arm':by_arm,'all_primary_evidence_unchanged':all(c['unchanged'] for c in checks),'primary_integrity':checks,'all_frozen_expected_and_saved_stdout_verdicts_independently_agree':all(x['independent_artifact_check']['all_verdicts_agree'] and x['independent_artifact_check']['all_expected_agree'] for x in X.values()),'availability':{'provider_quota_failure_slots':quota,'interpretation':'All started slots remain denominators. Quota failures preceded task reads and are not capture choices. Subsequent successful Codex sessions establish intermittent availability, not a stable global block.','qwen_unread_approval_slots':unread_qwen,'qwen_interpretation':'Literal function markup was emitted as text without actual tools. Exact admitted model later used tools; retained behavioral workflow failure, not established adapter incompatibility.'},'lifecycle_components':lifecycles,'phase_verdict':'No finance corpus/hidden-grading/carryforward fault found in these completed sessions. Continue frozen conditions subject to root common-input integrity gate; outcomes and qualified observer visibility limits do not justify repair or retries.','limits':['Only phase1 is complete. No strict six-stage handoff success yet.','Catalog direct lookup is from an exposed real key, not spontaneous key discovery.','Three of six successful policy reads coexist with complete prior policy code; do not infer exclusive memory dependence.','Initial faithful-policy capture is distinct from useful engineering capture and from full readback procedure adherence.','Aggregate total tests cannot validate per-line allocation order. Fable direct engine assertions can; see per-slot claims and supplements.','Normalized Codex command output can omit leading chunks present in authoritative actual model-facing rollouts; visibility observations are lower bounds. Frozen current admission gates unaffected.','GLM final response is in result.response; final-prose supplement records those checks.','Matched guidance comparisons remain small synthetic samples, with asymmetric quota failures and varying world/catalog assignments across profiles. No causal model-strength ranking.','Stage6 catalog orientation is shared workflow overhead; future no-curation verdict must not mean zero memory-related activity.'],'append_only_supplement_files':[p.name for p in sorted(A.glob('*.json')) if 'supplement' in p.name or 'correction' in p.name],'audit_sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(A.glob('*.json'))}}
f=A/f'phase1-final-{time.time_ns()}.json'
with f.open('x') as o:json.dump(report,o,indent=2)
print(f)
print(json.dumps({'by_arm':by_arm,'all_primary_evidence_unchanged':report['all_primary_evidence_unchanged'],'strict_false':sum(x['strict_six_stage_intersection'] is False for x in lifecycles),'strict_unverified':sum(x['strict_six_stage_intersection']=='unverified' for x in lifecycles)},indent=2))
